match process(&payload) {
    Ok(_) => consumer.commit_message(&msg, CommitMode::Async)?,
    Err(e) if permanent(&e) => {
        let rec = BaseRecord::to("orders.DLT")
            .key(&msg.key().map(Vec::from).unwrap_or_default())
            .payload(&payload);                 // headers: OwnedHeaders (topic/offset/error)
        dlt.send(rec).map_err(|(err, _)| err)?; // enqueue
        dlt.flush(Duration::from_secs(5))?;     // wait for delivery reports
        consumer.commit_message(&msg, CommitMode::Async)?;
    }
    Err(_) => {}                                // transient: do not commit, retry
}
